#ifndef TL_STORY_H
#define TL_STORY_H

#include <stdint.h>

#include "bn_string.h"
#include "bn_string_view.h"

#include "tl_map_id.h"
#include "tl_cast_data.h"
#include "tl_save.h"

// Story state and data: story flags, missions (log + objective), friendship per NPC, small-talk memory, City Coins and the
// player's name. The tables (dialogue pages, missions, NPC profiles) are GENERATED by tools/story_data.py from
// tools/dialogue_src.txt and the lists in that script; this header holds the shared structures.
namespace tl
{
    constexpr int npc_count = int(npc_id::count);
    constexpr int topic_count = 8;
    constexpr int gift_count = 5;               // see tools/story_data.py GIFTS
    constexpr int gossip_count = 8;             // see tools/story_data.py GOSSIP
    constexpr int mission_count = 23;           // see tools/story_data.py MISSIONS

    // ---------------------------------------------------------------------------------------------------- dialogue data
    enum class dlg_op : uint8_t
    {
        friend_delta,       // a = npc, b = delta
        money,              // b = delta
        set_flag,           // a = flag, b = value
        start_mission,      // b = mission id (index + 1)
        finish_mission,     // b = mission id
        coins               // b = City Coins
    };

    struct dlg_effect
    {
        dlg_op op;
        uint8_t a;
        int16_t b;
    };

    // One page of dialogue. Pages chain through `next`; a page may end with 2-4 choices instead.
    struct dlg_choice
    {
        const char* text;
        int16_t next;               // first page of the next node, -1 = end
        uint16_t effects_first;
        uint8_t effects_count;
    };

    constexpr int speaker_npc = 252;        // the NPC you are talking to
    constexpr int speaker_player = 253;     // {NAME}
    constexpr int speaker_system = 254;     // no portrait, no name tag

    struct dlg_node
    {
        const char* text;           // may contain {NAME}
        uint8_t speaker;            // npc_id, or speaker_*
        uint8_t effects_count;
        uint16_t effects_first;
        int16_t next;               // next page, -1 = end
        uint8_t choices_count;
        uint16_t choices_first;
        uint8_t expr;               // portrait expression: 0 neutral, 1 happy, 2 angry, 3 sad, 4 surprised
        int8_t cond_flag;           // `if <flag> -> node` / `ifnot <flag> -> node` after this page: flag index or -1
        uint8_t cond_negated;
        int16_t cond_next;
    };

    const dlg_node* dialogue_nodes();
    int dialogue_nodes_count();
    const dlg_effect* dialogue_effects();
    const dlg_choice* dialogue_choices();
    extern const int16_t dialogue_talk_nodes[npc_count][topic_count];
    extern const int16_t dialogue_greet_nodes[npc_count][3];     // good, neutral, grumpy
    extern const int16_t dialogue_bye_nodes[npc_count];
    extern const int16_t dialogue_intro_nodes[npc_count];
    extern const char* const topic_names[topic_count];
    extern const char* const topic_openers[topic_count];

    // ---------------------------------------------------------------------------------------------------- NPC profiles
    enum class npc_mood : uint8_t
    {
        good,
        neutral,
        grumpy
    };

    struct npc_info
    {
        const char* name;
        npc_mood base_mood;
        const char* likes;          // per topic: 'L' likes, 'N' neutral, 'D' dislikes
        uint8_t start_friendship;
        bool talks;                 // has small talk
        const char* gifts;          // per gift: 'F' favourite (+10), 'L' likes (+4), 'N' neutral (+1), 'D' dislikes (-3)
    };

    // Gift items (bought at the market / diner / kiosk, given in a conversation) and gossip rules (tools/story_data.py).
    struct gift_def
    {
        const char* name;
        int price;
    };

    struct gossip_rule
    {
        uint8_t kind;               // 0 = after a small-talk topic with `npc`, 1 = after a gift to `npc`
        uint8_t npc;
        uint8_t arg;                // topic or gift index
        uint8_t hearer;             // the NPC who brings it up
        int16_t node;               // dialogue page (its effects apply)
    };

    extern const gift_def gift_defs[gift_count];
    extern const gossip_rule gossip_rules[gossip_count];
    extern const int16_t dialogue_gift_fav_nodes[npc_count];

    extern const npc_info npc_infos[npc_count];

    // ---------------------------------------------------------------------------------------------------- missions
    enum class mission_cond : uint8_t
    {
        none,           // finished by a `done` effect
        talk,           // a = npc: finish a conversation with it
        enter_map,      // a = map
        money,          // b = dollars in the pocket
        flag,           // a = flag, b = minimum value
        day,            // a = first day
        time            // a = first day, b = minute of the day
    };

    struct mission_def
    {
        const char* code;           // "M02"
        const char* title;
        const char* objective;      // shown in the pause screen
        mission_cond cond;
        int a;
        int b;
        int next;                   // mission id started after this one (0 = none)
        int reward_money;
    };

    extern const mission_def mission_defs[mission_count];

    // What mission conditions are checked against.
    struct story_context
    {
        int day = 1;
        int minutes = 0;
        int money = 0;
        int map = 0;
        int talked_npc = -1;        // the NPC whose conversation just ended, or -1
    };

    // The weekday of a day number (Day 1 = Monday): "Monday" / "Mon".
    [[nodiscard]] const char* weekday_name(int day);
    [[nodiscard]] const char* weekday_short(int day);

    class story_state
    {

    public:
        static constexpr int max_flags = 80;
        static constexpr int name_max = 10;
        static constexpr int daily_talk_cap = 12;       // friendship points per NPC and day from small talk

        story_state();

        void new_game(const char* player_name);

        // player's name
        [[nodiscard]] const char* name() const
        {
            return _name;
        }

        // flags
        [[nodiscard]] int flag(int id) const
        {
            return (id >= 0 && id < max_flags) ? _flags[id] : 0;
        }

        void set_flag(int id, int value = 1);

        // friendship 0..100 per NPC
        [[nodiscard]] int friendship(int npc) const
        {
            return _friendship[npc];
        }

        void add_friendship(int npc, int delta);

        // City Coins
        [[nodiscard]] int coins() const
        {
            return _coins;
        }

        // Mood of an NPC today (decided by the day and the NPC, not saved).
        [[nodiscard]] npc_mood mood(int npc, int day, int minutes) const;

        // Small talk memory (3 game days) and daily limits.
        [[nodiscard]] int topic_uses(int npc, int topic, int day) const;
        void note_topic(int npc, int topic, int day);
        [[nodiscard]] bool first_talk_today(int npc, int day) const;
        void note_talk(int npc, int day);
        [[nodiscard]] int gained_today(int npc, int day) const;
        void note_gain(int npc, int day, int points);

        // City Coins: 3 when friendship has reached 70 (once), then 1 on the first conversation of the day, at most every third day.
        // Returns the coins granted now (0 if none).
        int check_coin_reward(int npc, int day, bool first_talk_today);

        // Applies a dialogue effect. Money is not applied here: it is collected for the field (take_money).
        void apply_effect(const dlg_effect& effect);

        [[nodiscard]] int take_money()
        {
            int value = _money_delta;
            _money_delta = 0;
            return value;
        }

        // Missions: ids are index + 1, 0 = none.
        [[nodiscard]] int mission() const
        {
            return _mission;
        }

        [[nodiscard]] bool mission_done(int id) const
        {
            return id > 0 && (_done_mask & (1u << (id - 1)));
        }

        void start_mission(int id);
        void finish_mission(int id);

        // Checks the current mission's condition. Returns the id of a mission that has just been completed (and starts the
        // next one), or 0.
        int check_mission(const story_context& context);

        [[nodiscard]] const char* objective() const;

        // The mission that was completed last and not yet shown to the player (0 = none).
        [[nodiscard]] int take_completed()
        {
            int id = _completed;
            _completed = 0;
            return id;
        }

        [[nodiscard]] int take_started()
        {
            int id = _started;
            _started = 0;
            return id;
        }

        // ---- gifts, gossip, scratch cards, Social (s63)
        [[nodiscard]] int item_count(int gift) const
        {
            return _items[gift];
        }

        [[nodiscard]] int items_total() const;
        void add_item(int gift, int count = 1);
        bool take_item(int gift);
        [[nodiscard]] bool gift_given_today(int npc, int day) const;
        void note_gift(int npc, int day);

        // Gossip: note_* remember a topic / gift; pending_gossip returns the rule index to tell `hearer` now (or -1).
        void note_gossip_topic(int npc, int topic, int day);
        void note_gossip_gift(int npc, int gift, int day);
        [[nodiscard]] int pending_gossip(int hearer, int day) const;
        void gossip_told(int rule);

        // Scratch cards: at most 3 per day.
        [[nodiscard]] int scratch_left(int day) const;
        void note_scratch(int day);

        // Social need changes made by conversations, collected for the field (like take_money).
        void add_social(int delta)
        {
            _social_delta += delta;
        }

        [[nodiscard]] int take_social()
        {
            int value = _social_delta;
            _social_delta = 0;
            return value;
        }

        // s71: "Feeling great" (all needs high), set by the field. Conversations add +1 to every positive friendship gain then.
        void set_great(bool great)
        {
            _great = great;
        }

        [[nodiscard]] bool feeling_great() const
        {
            return _great;
        }

        // s71: Lou has an odd job for today (taken at the notice board), set by the field before a conversation starts.
        void set_crates_open(bool open)
        {
            _crates_open = open;
        }

        [[nodiscard]] bool crates_open() const
        {
            return _crates_open;
        }

        void fill_save(save_data& out) const;
        void apply_save(const save_data& in);

    private:
        char _name[save_data::name_size] = {};
        uint8_t _flags[max_flags] = {};
        uint8_t _friendship[save_data::npc_slots] = {};
        uint8_t _topic_mem[save_data::talk_slots][topic_count] = {};
        uint8_t _talk_day[save_data::talk_slots] = {};
        uint8_t _gain_day[save_data::talk_slots] = {};
        uint8_t _gained[save_data::talk_slots] = {};
        uint8_t _coin_day[save_data::talk_slots] = {};
        uint8_t _coin70 = 0;
        uint16_t _coins = 0;
        uint16_t _mission = 0;
        uint32_t _done_mask = 0;
        int _money_delta = 0;
        int _social_delta = 0;
        bool _great = false;
        bool _crates_open = false;
        uint8_t _items[gift_count] = {};
        uint8_t _gift_day[save_data::talk_slots] = {};
        uint8_t _gossip[gossip_count] = {};         // 0 = none, 1..250 = day marker when noted, 255 = told
        uint8_t _scratch_day = 0;
        uint8_t _scratch_count = 0;
        int _completed = 0;
        int _started = 0;
    };

    // The one story state of the running game.
    [[nodiscard]] story_state& story();
}

#endif
